/**
 * Collection of helper utilities for debugging and visualizing SDF volumes.
 *
 * **Overview**
 * These helpers provide visual feedback for SDF generation and sampling, which is crucial for debugging:
 * - **Bounds Helper**: Visualizes the volume extent.
 * - **Point Cloud**: Visualizes sampled points to verify distribution and containment.
 * - **Debug Grid**: Visualizes the SDF values (distance field) directly using a grid of spheres.
 *
 * @module SDFVolumeHelpers
 * @short Debug helpers to visualize SDF bounds, sampled points, and grid probes.
 * @category Compute
 * @tags WebGPU
 */
/**
 * Creates a Box3Helper for visualizing SDF volume bounds.
 *
 * @param {ComputeSDFGenerator} sdfGenerator - SDF generator instance.
 * @param {number} [color=0xffff00] - Helper line color.
 * @returns {THREE.Box3Helper} Box helper for SDF bounds.
 *
 * @example
 * import { createSDFBoundsHelper } from '@three-blocks/core';
 *
 * const boundsHelper = createSDFBoundsHelper(sdfGenerator);
 * scene.add(boundsHelper);
 *
 * // Update when SDF regenerates
 * await sdfGenerator.generate(mesh, bvh, renderer);
 * updateSDFBoundsHelper(boundsHelper, sdfGenerator);
 */
export function createSDFBoundsHelper(sdfGenerator: ComputeSDFGenerator, color?: number): THREE.Box3Helper;
/**
 * Updates an existing Box3Helper to match current SDF bounds.
 *
 * @param {THREE.Box3Helper} helper - Existing Box3Helper.
 * @param {ComputeSDFGenerator} sdfGenerator - SDF generator instance.
 *
 * @example
 * // After regenerating SDF
 * await sdfGenerator.generate(mesh, bvh, renderer);
 * updateSDFBoundsHelper(boundsHelper, sdfGenerator);
 */
export function updateSDFBoundsHelper(helper: THREE.Box3Helper, sdfGenerator: ComputeSDFGenerator): void;
/**
 * Creates a point cloud visualization of sampled positions.
 *
 * @param {ComputeBVHSampler} sampler - BVH sampler instance.
 * @param {Object} [options] - Configuration options.
 * @param {number} [options.pointSize=2] - Point size in pixels.
 * @param {number} [options.color=0x00ffff] - Point color.
 * @returns {Promise<THREE.Points>} Points mesh for visualization.
 *
 * @example
 * import { createSDFPointCloudHelper } from '@three-blocks/core';
 *
 * await sampler.compute();
 * const pointCloud = await createSDFPointCloudHelper(sampler, {
 *   pointSize: 3,
 *   color: 0xff00ff
 * });
 * scene.add(pointCloud);
 */
export function createSDFPointCloudHelper(sampler: ComputeBVHSampler, options?: {
    pointSize?: number;
    color?: number;
}): Promise<THREE.Points>;
/**
 * Creates a grid of spheres showing SDF sample locations (for debugging sampling).
 *
 * @param {ComputeSDFGenerator} sdfGenerator - SDF generator instance.
 * @param {Object} [options] - Configuration options.
 * @param {number} [options.gridSize=8] - Number of samples per axis.
 * @param {number} [options.sphereRadius=0.02] - Sphere radius.
 * @param {Function} [options.colorFn] - Custom color function: `(sdfValue) => THREE.Color`.
 * @returns {THREE.Group} Group containing sphere instances.
 *
 * @example
 * import { createSDFDebugGrid } from '@three-blocks/core';
 *
 * const debugGrid = createSDFDebugGrid(sdfGenerator, {
 *   gridSize: 10,
 *   colorFn: (dist) => dist < 0 ? new THREE.Color(0xff0000) : new THREE.Color(0x00ff00)
 * });
 * scene.add(debugGrid);
 */
export function createSDFDebugGrid(sdfGenerator: ComputeSDFGenerator, options?: {
    gridSize?: number;
    sphereRadius?: number;
    colorFn?: Function;
}): THREE.Group;
